package com.bank.rsocket.controller;

import com.bank.rsocket.dto.PriceTick;
import lombok.extern.slf4j.Slf4j;
import org.springframework.messaging.handler.annotation.MessageMapping;
import org.springframework.stereotype.Controller;
import reactor.core.publisher.Flux;
import java.math.BigDecimal;
import java.time.Duration;

@Slf4j
@Controller
public class PriceController {

    // Fast producer: a tick every 50ms. The RSocket layer will only push
    // as many as the consumer's request(n) demand allows (backpressure).
    @MessageMapping("price.stream")
    public Flux<PriceTick> priceStream(String symbol) {
        return Flux.interval(Duration.ofMillis(50))
            .map(seq -> new PriceTick(symbol,
                    new BigDecimal("2450").add(BigDecimal.valueOf(seq)), seq))
            // log server-side emission so we can SEE it pace to demand
            .doOnRequest(n -> log.info("Server received demand request({}) for {}", n, symbol))
            .doOnNext(t -> log.info("Server emits tick {} (within demand)", t.seq()))
            .take(20);
    }
}
