package com.bank.rsocket.client;

import com.bank.rsocket.dto.PriceTick;
import lombok.extern.slf4j.Slf4j;
import org.springframework.messaging.rsocket.RSocketRequester;
import reactor.core.publisher.BaseSubscriber;
import reactor.core.publisher.Flux;

@Slf4j
public class BackpressureClient {
    private final RSocketRequester requester;
    public BackpressureClient(RSocketRequester requester) { this.requester = requester; }

    public void subscribeSlowRenderer(String symbol) {
        Flux<PriceTick> ticks = requester.route("price.stream").data(symbol)
            .retrieveFlux(PriceTick.class);

        // Custom subscriber = slow UI that can only render 3 ticks at a time.
        ticks.subscribe(new BaseSubscriber<>() {
            @Override
            protected void hookOnSubscribe(reactor.core.publisher.FluxSink.OverflowStrategy ignore) {
                // (illustrative) initial demand of 3
            }
            @Override
            protected void hookOnSubscribe(org.reactivestreams.Subscription subscription) {
                log.info("Client requests FIRST batch of 3 (what the UI can render)");
                request(3); // demand-based: pull only 3 to start
            }
            @Override
            protected void hookOnNext(PriceTick tick) {
                log.info("Client rendered tick {} Rs.{}", tick.seq(), tick.price());
                simulateSlowRender();
                // after rendering the batch, ask for 3 more → request(n) over the wire
                if (tick.seq() % 3 == 2) {
                    log.info("UI free again → request 3 more");
                    request(3);
                }
            }
        });
    }

    private void simulateSlowRender() {
        try { Thread.sleep(300); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
    }
}
